import{_ as a,o as t,c as n,am as o}from"./chunks/framework.pMGCiGo2.js";const h=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),r={name:"glossaire.md"};function i(s,e,l,u,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="capacite" tabindex="-1">Capacité <a class="header-anchor" href="#capacite" aria-label="Permalink to &quot;Capacité&quot;">​</a></h3><p>Quantité de travail que l&#39;équipe peut prendre dans un sprint donné, compte tenu des absences.</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="connecteur" tabindex="-1">Connecteur <a class="header-anchor" href="#connecteur" aria-label="Permalink to &quot;Connecteur&quot;">​</a></h3><p>Dans Claude (Desktop ou claude.ai), le branchement d&#39;un serveur MCP sur l&#39;assistant : une fois connecté, l&#39;assistant peut lire (et parfois écrire) dans l&#39;outil, avec tes droits.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="cycle-time" tabindex="-1">Cycle time <a class="header-anchor" href="#cycle-time" aria-label="Permalink to &quot;Cycle time&quot;">​</a></h3><p>Durée écoulée entre le début du travail sur une story et sa fin.</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="dod-definition-of-done" tabindex="-1">DoD (Definition of Done) <a class="header-anchor" href="#dod-definition-of-done" aria-label="Permalink to &quot;DoD (Definition of Done)&quot;">​</a></h3><p>Liste de critères qu&#39;un travail doit remplir pour être considéré comme terminé.</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="instructions-personnalisees-assistant-personnalise" tabindex="-1">Instructions personnalisées / assistant personnalisé <a class="header-anchor" href="#instructions-personnalisees-assistant-personnalise" aria-label="Permalink to &quot;Instructions personnalisées / assistant personnalisé&quot;">​</a></h3><p>Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).</p><h3 id="jeu-de-role" tabindex="-1">Jeu de rôle <a class="header-anchor" href="#jeu-de-role" aria-label="Permalink to &quot;Jeu de rôle&quot;">​</a></h3><p>Répétition d&#39;une conversation où l&#39;IA joue un personnage (un manager pressé, un développeur sceptique…), pour s&#39;y préparer.</p><h3 id="llm-large-language-model" tabindex="-1">LLM (Large Language Model) <a class="header-anchor" href="#llm-large-language-model" aria-label="Permalink to &quot;LLM (Large Language Model)&quot;">​</a></h3><p>Modèle entraîné sur d&#39;énormes volumes de texte, qui génère une réponse en prédisant le mot suivant.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>Standard pour brancher de nouveaux tools sur un assistant : applications et données de l&#39;entreprise.</p><h3 id="mediane" tabindex="-1">Médiane <a class="header-anchor" href="#mediane" aria-label="Permalink to &quot;Médiane&quot;">​</a></h3><p>Valeur du milieu quand on range les valeurs dans l&#39;ordre : moins sensible qu&#39;une moyenne à une valeur extrême.</p><h3 id="pms" tabindex="-1">PMS <a class="header-anchor" href="#pms" aria-label="Permalink to &quot;PMS&quot;">​</a></h3><p>Système de gestion de l&#39;hôtel : réservations, état des chambres, note du client.</p><h3 id="product-backlog" tabindex="-1">Product Backlog <a class="header-anchor" href="#product-backlog" aria-label="Permalink to &quot;Product Backlog&quot;">​</a></h3><p>Liste ordonnée de ce qui reste à faire sur le produit, sous la responsabilité du Product Owner.</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="recette" tabindex="-1">Recette <a class="header-anchor" href="#recette" aria-label="Permalink to &quot;Recette&quot;">​</a></h3><p>Vérification, avant la mise en service, que ce qui a été développé respecte les critères d&#39;acceptation. L&#39;environnement de recette sert à ces essais.</p><h3 id="securite-psychologique" tabindex="-1">Sécurité psychologique <a class="header-anchor" href="#securite-psychologique" aria-label="Permalink to &quot;Sécurité psychologique&quot;">​</a></h3><p>Le sentiment, dans une équipe, de pouvoir dire un blocage, un doute ou une erreur sans craindre d&#39;être jugé.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h3><p>Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l&#39;assistant charge à la demande, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d&#39;« Agent Skills » ; d&#39;autres assistants ont des équivalents.</p><h3 id="smart-action" tabindex="-1">SMART (action) <a class="header-anchor" href="#smart-action" aria-label="Permalink to &quot;SMART (action)&quot;">​</a></h3><p>Une action spécifique, mesurable, atteignable, pertinente et limitée dans le temps.</p><h3 id="sprint-backlog" tabindex="-1">Sprint Backlog <a class="header-anchor" href="#sprint-backlog" aria-label="Permalink to &quot;Sprint Backlog&quot;">​</a></h3><p>Le Sprint Goal, les éléments retenus pour le sprint et le plan pour les livrer : il appartient aux développeurs.</p><h3 id="sprint-goal" tabindex="-1">Sprint Goal <a class="header-anchor" href="#sprint-goal" aria-label="Permalink to &quot;Sprint Goal&quot;">​</a></h3><p>L&#39;objectif du sprint, en une phrase : la valeur visée. Il donne une boussole quand le plan change en cours de sprint.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (tool calling).</p><h3 id="transcription" tabindex="-1">Transcription <a class="header-anchor" href="#transcription" aria-label="Permalink to &quot;Transcription&quot;">​</a></h3><p>Texte produit automatiquement à partir de l&#39;enregistrement d&#39;une réunion. Elle peut contenir des trous et des erreurs.</p><h3 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h3><p>Description courte d&#39;un besoin du point de vue de l&#39;utilisateur : « En tant que…, je veux…, afin de… ».</p><h3 id="velocite" tabindex="-1">Vélocité <a class="header-anchor" href="#velocite" aria-label="Permalink to &quot;Vélocité&quot;">​</a></h3><p>Quantité de travail, en points, que l&#39;équipe termine en moyenne par sprint.</p><h3 id="wip-work-in-progress" tabindex="-1">WIP (work in progress) <a class="header-anchor" href="#wip-work-in-progress" aria-label="Permalink to &quot;WIP (work in progress)&quot;">​</a></h3><p>Nombre de stories en cours en même temps.</p>',67)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
